CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY NOT NULL, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, preferred_language TEXT NOT NULL DEFAULT 'fa', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS skills (id TEXT PRIMARY KEY NOT NULL, exam_code TEXT NOT NULL, title TEXT NOT NULL, source_url TEXT NOT NULL, source_version TEXT NOT NULL, reviewed_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS lessons (id TEXT PRIMARY KEY NOT NULL, skill_id TEXT NOT NULL, content_key TEXT NOT NULL, source_url TEXT NOT NULL, estimated_minutes INTEGER NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS questions (id TEXT PRIMARY KEY NOT NULL, skill_id TEXT NOT NULL, content_key TEXT NOT NULL, source_url TEXT NOT NULL, review_status TEXT NOT NULL DEFAULT 'draft', is_original INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS attempts (id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL, question_id TEXT NOT NULL, selected_answer INTEGER NOT NULL, is_correct INTEGER NOT NULL, answered_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS flashcards (id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL, question_id TEXT NOT NULL, box INTEGER NOT NULL DEFAULT 1, due_at INTEGER NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS labs (id TEXT PRIMARY KEY NOT NULL, skill_id TEXT NOT NULL, content_key TEXT NOT NULL, source_url TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS lab_submissions (id TEXT PRIMARY KEY NOT NULL, lab_id TEXT NOT NULL, user_id TEXT NOT NULL, evidence_text TEXT NOT NULL, evidence_url TEXT, completed_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS progress (user_id TEXT PRIMARY KEY NOT NULL, lesson_id TEXT NOT NULL, completion_percent INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
